-- Matkatalogen från supabase/katalog/mat/adventure-food.csv, supabase/katalog/mat/adventure-menu.csv, supabase/katalog/mat/bla-band.csv, supabase/katalog/mat/emergency-food.csv, supabase/katalog/mat/lyofood.csv, supabase/katalog/mat/real-turmat.csv, supabase/katalog/mat/summit-to-eat.csv, supabase/katalog/mat/travellunch.csv, supabase/katalog/mat/trekn-eat.csv.
-- Skapad med "npm run matkatalog". Ändra inte filen för hand: ändra CSV:n och skapa en ny migrering.

on conflict (lower(marke), lower(namn)) do update set
  marke = excluded.marke,
  namn = excluded.namn,
  andra_namn = excluded.andra_namn,
  maltid = excluded.maltid,
  torkning = excluded.torkning,
  vikt_torr_g = excluded.vikt_torr_g,
  portioner = excluded.portioner,
  kcal = excluded.kcal,
  protein_g = excluded.protein_g,
  fett_g = excluded.fett_g,
  kolhydrater_g = excluded.kolhydrater_g,
  vatten_ml = excluded.vatten_ml,
  tillagning_vatten = excluded.tillagning_vatten,
  tillagning_min = excluded.tillagning_min,
  vegetarisk = excluded.vegetarisk,
  vegansk = excluded.vegansk,
  glutenfri = excluded.glutenfri,
  laktosfri = excluded.laktosfri,
  allergener = excluded.allergener,
  spar = excluded.spar,
  pris_sek_ca = excluded.pris_sek_ca,
  pris_kalla = excluded.pris_kalla,
  kalla = excluded.kalla,
  kontrollerad = excluded.kontrollerad;
